// Relative URL: resolved against <base href>, i.e. the ingress prefix.
const cell = document.getElementById("health");

try {
  const res = await fetch("api/health", { headers: { Accept: "application/json" } });
  if (!res.ok) throw new Error(`HTTP ${res.status}`);
  const body = await res.json();
  cell.textContent = `✅ ${body.status}, Basis-Pfad ${body.base_path}, Uptime ${body.uptime_s} s`;
} catch (err) {
  cell.textContent = `❌ ${err.message}`;
  cell.classList.add("error");
}
